function normalizeDomain(input) {
    const trimmed = input.trim();
    if (!trimmed)
        return null;
    try {
        const url = trimmed.includes("://") ? new URL(trimmed) : new URL(`https://${trimmed}`);
        return url.hostname;
    }
    catch {
        return null;
    }
}

function getUrls(domain) {
    return {
        deviceCodeUrl: `https://${domain}/login/device/code`,
        accessTokenUrl: `https://${domain}/login/oauth/access_token`,
        copilotTokenUrl: `https://api.${domain}/copilot_internal/v2/token`,
    };
}

function getBaseUrlFromToken(token) {
    const match = token.match(/proxy-ep=([^;]+)/);
    if (!match)
        return null;
    const proxyHost = match[1];
    // Convert proxy.xxx to api.xxx
    const apiHost = proxyHost.replace(/^proxy\./, "api.");
    return `https://${apiHost}`;
}

function getGitHubCopilotBaseUrl(token, enterpriseDomain) {
    // If we have a token, extract the base URL from proxy-ep
    if (token) {
        const urlFromToken = getBaseUrlFromToken(token);
        if (urlFromToken)
            return urlFromToken;
    }
    // Fallback for enterprise or if token parsing fails
    if (enterpriseDomain)
        return `https://copilot-api.${enterpriseDomain}`;
    return "https://api.individual.githubcopilot.com";
}

function asRecord(value) {
    return value && typeof value === "object" ? value : undefined;
}

function parseGitHubCopilotModelCatalog(raw, allowPolicyFallback) {
    const data = asRecord(raw)?.data;
    if (!Array.isArray(data)) {
        throw new Error("Invalid Copilot models response");
    }
    const accountModels = data.flatMap((rawItem) => {
        const item = asRecord(rawItem);
        const id = item?.id;
        if (!item || typeof id !== "string")
            return [];
        const capabilities = asRecord(item.capabilities);
        const supports = asRecord(capabilities?.supports);
        if (supports?.tool_calls === false)
            return [];
        return [
            {
                id,
                pickerEnabled: item.model_picker_enabled === true,
                policyState: asRecord(item.policy)?.state,
            },
        ];
    });
    const pickerModelIds = accountModels
        .filter((model) => model.pickerEnabled && model.policyState !== "disabled")
        .map((model) => model.id);
    const usePolicyFallback = allowPolicyFallback && pickerModelIds.length === 0;
    const availableModelIds = pickerModelIds.length > 0 || !allowPolicyFallback
        ? pickerModelIds
        : accountModels.filter((model) => model.policyState === "enabled").map((model) => model.id);
    const policyModelIds = accountModels
        .filter((model) => model.policyState === "unconfigured" &&
        Object.hasOwn(GITHUB_COPILOT_MODELS, model.id) &&
        (model.pickerEnabled || usePolicyFallback))
        .map((model) => model.id);
    return { availableModelIds, policyModelIds };
}

async function fetchWithRateLimitRetry(url, init, signal, retryPolicy) {
    const retryBudgetSignal = retryPolicy.maxRetries > 0 && retryPolicy.maxElapsedMs > 0
        ? AbortSignal.timeout(retryPolicy.maxElapsedMs)
        : undefined;
    const requestSignal = retryBudgetSignal ? AbortSignal.any([signal, retryBudgetSignal]) : signal;
    const retryDeadline = retryBudgetSignal ? Date.now() + retryPolicy.maxElapsedMs : undefined;
    for (let retry = 0;; retry++) {
        const response = await fetch(url, {
            ...init,
            signal: AbortSignal.any([requestSignal, AbortSignal.timeout(5000)]),
        });
        if (response.status !== 429 || retry === retryPolicy.maxRetries)
            return response;
        const retryAfter = response.headers.get("retry-after");
        let delayMs = 500 * 2 ** retry;
        if (retryAfter) {
            const seconds = Number.parseFloat(retryAfter);
            delayMs = Number.isNaN(seconds) ? Date.parse(retryAfter) - Date.now() : seconds * 1000;
            if (!Number.isFinite(delayMs))
                return response;
        }
        delayMs = Math.max(0, delayMs);
        if (retryDeadline !== undefined && delayMs >= retryDeadline - Date.now())
            return response;
        await response.body?.cancel();
        await sleep(delayMs, requestSignal);
    }
}

async function fetchGitHubCopilotModels(copilotToken, enterpriseDomain, signal, retryPolicy) {
    const baseUrl = getGitHubCopilotBaseUrl(copilotToken, enterpriseDomain);
    // Some Individual accounts return false for every picker flag despite explicit enabled policies.
    // Limit the fallback to that endpoint so other account types keep strict picker semantics.
    const allowPolicyFallback = baseUrl === "https://api.individual.githubcopilot.com";
    const response = await fetchWithRateLimitRetry(`${baseUrl}/models`, {
        headers: {
            Accept: "application/json",
            Authorization: `Bearer ${copilotToken}`,
            ...COPILOT_HEADERS,
            "X-GitHub-Api-Version": COPILOT_API_VERSION,
        },
    }, signal, retryPolicy);
    if (!response.ok) {
        throw new Error(`${response.status} ${response.statusText}: ${await response.text()}`);
    }
    return parseGitHubCopilotModelCatalog(await response.json(), allowPolicyFallback);
}

async function fetchJson(url, init) {
    const response = await fetch(url, init);
    if (!response.ok) {
        const text = await response.text();
        throw new Error(`${response.status} ${response.statusText}: ${text}`);
    }
    return response.json();
}

async function startDeviceFlow(domain, signal) {
    const urls = getUrls(domain);
    const data = await fetchJson(urls.deviceCodeUrl, {
        method: "POST",
        headers: {
            Accept: "application/json",
            "Content-Type": "application/x-www-form-urlencoded",
            "User-Agent": "GitHubCopilotChat/0.35.0",
        },
        body: new URLSearchParams({
            client_id: CLIENT_ID,
            scope: "read:user",
        }),
        signal,
    });
    if (!data || typeof data !== "object") {
        throw new Error("Invalid device code response");
    }
    const deviceCode = data.device_code;
    const userCode = data.user_code;
    const verificationUri = data.verification_uri;
    const interval = data.interval;
    const expiresIn = data.expires_in;
    if (typeof deviceCode !== "string" ||
        typeof userCode !== "string" ||
        typeof verificationUri !== "string" ||
        (interval !== undefined && typeof interval !== "number") ||
        typeof expiresIn !== "number") {
        throw new Error("Invalid device code response fields");
    }
    // The verification URI is opened in the user's browser and to prevent `open` from
    // opening an executable or similar, we force it to be a URL.
    let parsedUri;
    try {
        parsedUri = new URL(verificationUri);
    }
    catch {
        throw new Error("Untrusted verification_uri in device code response");
    }
    if (parsedUri.protocol !== "https:" && parsedUri.protocol !== "http:") {
        throw new Error("Untrusted verification_uri in device code response");
    }
    return {
        device_code: deviceCode,
        user_code: userCode,
        verification_uri: parsedUri.href,
        interval,
        expires_in: expiresIn,
    };
}

async function pollForGitHubAccessToken(domain, device, signal) {
    const urls = getUrls(domain);
    return pollOAuthDeviceCodeFlow({
        intervalSeconds: device.interval,
        expiresInSeconds: device.expires_in,
        waitBeforeFirstPoll: true,
        signal,
        poll: async () => {
            const raw = await fetchJson(urls.accessTokenUrl, {
                method: "POST",
                headers: {
                    Accept: "application/json",
                    "Content-Type": "application/x-www-form-urlencoded",
                    "User-Agent": "GitHubCopilotChat/0.35.0",
                },
                body: new URLSearchParams({
                    client_id: CLIENT_ID,
                    device_code: device.device_code,
                    grant_type: "urn:ietf:params:oauth:grant-type:device_code",
                }),
                signal,
            });
            if (raw && typeof raw === "object" && typeof raw.access_token === "string") {
                return { status: "complete", value: raw.access_token };
            }
            if (raw && typeof raw === "object" && typeof raw.error === "string") {
                const { error, error_description: description, interval } = raw;
                if (error === "authorization_pending") {
                    return { status: "pending" };
                }
                if (error === "slow_down") {
                    return { status: "slow_down", intervalSeconds: typeof interval === "number" ? interval : undefined };
                }
                const descriptionSuffix = description ? `: ${description}` : "";
                return { status: "failed", message: `Device flow failed: ${error}${descriptionSuffix}` };
            }
            return { status: "failed", message: "Invalid device token response" };
        },
    });
}

async function refreshGitHubCopilotAccessToken(refreshToken, enterpriseDomain, signal) {
    const domain = enterpriseDomain || "github.com";
    const urls = getUrls(domain);
    const raw = await fetchJson(urls.copilotTokenUrl, {
        headers: {
            Accept: "application/json",
            Authorization: `Bearer ${refreshToken}`,
            ...COPILOT_HEADERS,
        },
        signal,
    });
    if (!raw || typeof raw !== "object") {
        throw new Error("Invalid Copilot token response");
    }
    const token = raw.token;
    const expiresAt = raw.expires_at;
    if (typeof token !== "string" || typeof expiresAt !== "number") {
        throw new Error("Invalid Copilot token response fields");
    }
    return {
        type: "oauth",
        refresh: refreshToken,
        access: token,
        expires: expiresAt * 1000 - 5 * 60 * 1000,
        enterpriseUrl: enterpriseDomain,
    };
}

async function refreshGitHubCopilotToken(refreshToken, enterpriseDomain, signal) {
    const credentials = await refreshGitHubCopilotAccessToken(refreshToken, enterpriseDomain, signal);
    const { availableModelIds } = await fetchGitHubCopilotModels(credentials.access, enterpriseDomain, signal, {
        maxRetries: 0,
        maxElapsedMs: 0,
    });
    return {
        ...credentials,
        availableModelIds,
    };
}

async function enableGitHubCopilotModel(token, modelId, enterpriseDomain, signal) {
    const baseUrl = getGitHubCopilotBaseUrl(token, enterpriseDomain);
    const url = `${baseUrl}/models/${modelId}/policy`;
    let response;
    try {
        response = await fetchWithRateLimitRetry(url, {
            method: "POST",
            headers: {
                "Content-Type": "application/json",
                Authorization: `Bearer ${token}`,
                ...COPILOT_HEADERS,
                "openai-intent": "chat-policy",
                "x-interaction-type": "chat-policy",
            },
            body: JSON.stringify({ state: "enabled" }),
        }, signal, { maxRetries: 2, maxElapsedMs: 5000 });
    }
    catch (error) {
        if (signal.aborted)
            throw error;
        return false;
    }
    if (response.status === 429) {
        throw new Error(`${response.status} ${response.statusText}: ${await response.text()}`);
    }
    return response.ok;
}

async function enableGitHubCopilotModels(token, modelIds, enterpriseDomain, signal) {
    const enabledModelIds = [];
    for (const modelId of modelIds) {
        try {
            if (await enableGitHubCopilotModel(token, modelId, enterpriseDomain, signal)) {
                enabledModelIds.push(modelId);
            }
        }
        catch (error) {
            if (signal.aborted)
                throw error;
            break;
        }
    }
    return enabledModelIds;
}

async function loginGitHubCopilot(interaction) {
    const input = await interaction.prompt({
        type: "text",
        message: "GitHub Enterprise URL/domain (blank for github.com)",
        placeholder: "company.ghe.com",
    });
    if (interaction.signal.aborted)
        throw new Error("Login cancelled");
    const trimmed = input.trim();
    const enterpriseDomain = normalizeDomain(input);
    if (trimmed && !enterpriseDomain)
        throw new Error("Invalid GitHub Enterprise URL/domain");
    const domain = enterpriseDomain || "github.com";
    const device = await startDeviceFlow(domain, interaction.signal);
    interaction.notify({
        type: "device_code",
        userCode: device.user_code,
        verificationUri: device.verification_uri,
        intervalSeconds: device.interval,
        expiresInSeconds: device.expires_in,
    });
    const githubAccessToken = await pollForGitHubAccessToken(domain, device, interaction.signal);
    const credentials = await refreshGitHubCopilotAccessToken(githubAccessToken, enterpriseDomain ?? undefined, interaction.signal);
    const models = await fetchGitHubCopilotModels(credentials.access, enterpriseDomain ?? undefined, interaction.signal, {
        maxRetries: 2,
        maxElapsedMs: 5000,
    });
    let enabledModelIds = [];
    if (models.policyModelIds.length > 0) {
        interaction.notify({ type: "progress", message: "Enabling models..." });
        enabledModelIds = await enableGitHubCopilotModels(credentials.access, models.policyModelIds, enterpriseDomain ?? undefined, interaction.signal);
    }
    return {
        ...credentials,
        availableModelIds: [...new Set([...models.availableModelIds, ...enabledModelIds])],
    };
}

function copilotEnterpriseDomain(credential) {
    const enterpriseUrl = credential.enterpriseUrl;
    if (typeof enterpriseUrl !== "string" || !enterpriseUrl)
        return undefined;
    return normalizeDomain(enterpriseUrl) ?? undefined;
}

async toAuth(credential) {
        return {
            apiKey: credential.access,
            baseUrl: getGitHubCopilotBaseUrl(credential.access, copilotEnterpriseDomain(credential)),
        };
    }

function getOauthHost() {
    const override = getProviderEnvValue("KIMI_CODE_OAUTH_HOST") || getProviderEnvValue("KIMI_OAUTH_HOST");
    return (override || DEFAULT_OAUTH_HOST).replace(/\/+$/, "");
}

function requestSignal(signal) {
    return AbortSignal.any([AbortSignal.timeout(REQUEST_TIMEOUT_MS), signal]);
}

function formUrlEncode(fields) {
    return new URLSearchParams(fields).toString();
}

async function readJson(response) {
    try {
        const json = await response.json();
        return json && typeof json === "object" ? json : null;
    }
    catch {
        return null;
    }
}

function trustedHttpUrl(value) {
    if (typeof value !== "string" || !value)
        return null;
    try {
        const url = new URL(value);
        if (url.protocol !== "https:" && url.protocol !== "http:")
            return null;
        return url.href;
    }
    catch {
        return null;
    }
}

async function startDeviceAuthorization(oauthHost, signal) {
    const response = await fetch(`${oauthHost}/api/oauth/device_authorization`, {
        method: "POST",
        headers: {
            "Content-Type": "application/x-www-form-urlencoded",
            Accept: "application/json",
        },
        body: formUrlEncode({ client_id: CLIENT_ID }),
        signal: requestSignal(signal),
    });
    if (!response.ok) {
        const text = await response.text().catch(() => "");
        throw new Error(`Kimi Code device authorization failed with status ${response.status}${text ? `: ${text}` : ""}`);
    }
    const json = await readJson(response);
    const deviceCode = json?.device_code;
    const userCode = json?.user_code;
    const verificationUri = json?.verification_uri;
    const verificationUriComplete = json?.verification_uri_complete;
    if (typeof deviceCode !== "string" ||
        typeof userCode !== "string" ||
        typeof verificationUri !== "string" ||
        typeof verificationUriComplete !== "string" ||
        !trustedHttpUrl(verificationUriComplete) ||
        !trustedHttpUrl(verificationUri)) {
        throw new Error(`Invalid Kimi Code device authorization response: ${JSON.stringify(json)}`);
    }
    const interval = json?.interval;
    const expiresIn = json?.expires_in;
    return {
        deviceCode,
        userCode,
        verificationUri,
        verificationUriComplete,
        intervalSeconds: typeof interval === "number" && Number.isFinite(interval) && interval > 0
            ? interval
            : DEFAULT_POLL_INTERVAL_SECONDS,
        expiresInSeconds: typeof expiresIn === "number" && Number.isFinite(expiresIn) && expiresIn > 0
            ? expiresIn
            : DEVICE_CODE_TIMEOUT_SECONDS,
    };
}

function parseTokenResponse(json, operation) {
    const accessToken = json?.access_token;
    const refreshToken = json?.refresh_token;
    const expiresIn = json?.expires_in;
    if (typeof accessToken !== "string" ||
        !accessToken ||
        typeof refreshToken !== "string" ||
        !refreshToken ||
        typeof expiresIn !== "number" ||
        !Number.isFinite(expiresIn) ||
        expiresIn <= 0) {
        throw new Error(`Kimi Code token ${operation} response missing fields: ${JSON.stringify(json)}`);
    }
    return {
        access: accessToken,
        refresh: refreshToken,
        expires: Date.now() + expiresIn * 1000,
    };
}

async function pollForToken(oauthHost, device, signal) {
    return pollOAuthDeviceCodeFlow({
        intervalSeconds: device.intervalSeconds,
        expiresInSeconds: device.expiresInSeconds,
        waitBeforeFirstPoll: true,
        signal,
        poll: async () => {
            const response = await fetch(`${oauthHost}/api/oauth/token`, {
                method: "POST",
                headers: {
                    "Content-Type": "application/x-www-form-urlencoded",
                    Accept: "application/json",
                },
                body: formUrlEncode({
                    client_id: CLIENT_ID,
                    device_code: device.deviceCode,
                    grant_type: "urn:ietf:params:oauth:grant-type:device_code",
                }),
                signal: requestSignal(signal),
            });
            if (response.status >= 500) {
                const text = await response.text().catch(() => "");
                return {
                    status: "failed",
                    message: `Kimi Code device token request failed with status ${response.status}${text ? `: ${text}` : ""}`,
                };
            }
            const json = await readJson(response);
            if (response.ok && typeof json?.access_token === "string") {
                try {
                    return { status: "complete", value: parseTokenResponse(json, "poll") };
                }
                catch (error) {
                    return { status: "failed", message: error instanceof Error ? error.message : String(error) };
                }
            }
            const error = json?.error;
            const description = typeof json?.error_description === "string" ? `: ${json.error_description}` : "";
            if (error === "authorization_pending") {
                return { status: "pending" };
            }
            if (error === "slow_down") {
                const interval = json?.interval;
                return {
                    status: "slow_down",
                    intervalSeconds: typeof interval === "number" && interval > 0 ? interval : undefined,
                };
            }
            if (error === "expired_token") {
                return { status: "failed", message: "Kimi Code device authorization expired. Please restart login." };
            }
            if (error === "access_denied") {
                return { status: "failed", message: "Kimi Code login was denied." };
            }
            return {
                status: "failed",
                message: `Kimi Code device token request failed (status ${response.status})${typeof error === "string" ? `: ${error}${description}` : ""}`,
            };
        },
    });
}

function isRetryableRefreshFailure(response) {
    return response.status === 429 || response.status >= 500;
}

async function refreshToken(oauthHost, refreshTokenValue, signal) {
    let lastError;
    for (let attempt = 0; attempt <= REFRESH_MAX_RETRIES; attempt++) {
        if (attempt > 0) {
            await sleep(1000 * 2 ** (attempt - 1), signal);
        }
        if (signal.aborted) {
            throw new Error("Kimi Code token refresh aborted");
        }
        let response;
        try {
            response = await fetch(`${oauthHost}/api/oauth/token`, {
                method: "POST",
                headers: {
                    "Content-Type": "application/x-www-form-urlencoded",
                    Accept: "application/json",
                },
                body: formUrlEncode({
                    client_id: CLIENT_ID,
                    grant_type: "refresh_token",
                    refresh_token: refreshTokenValue,
                }),
                signal: requestSignal(signal),
            });
        }
        catch (error) {
            lastError = error instanceof Error ? error : new Error(String(error));
            continue;
        }
        const json = await readJson(response);
        if (response.ok) {
            return parseTokenResponse(json, "refresh");
        }
        // Unauthorized: the stored credential is dead; Models clears it and prompts re-login.
        if (response.status === 401 || response.status === 403 || json?.error === "invalid_grant") {
            const description = typeof json?.error_description === "string" ? `: ${json.error_description}` : "";
            throw new Error(`Kimi Code token refresh unauthorized (status ${response.status})${description}`);
        }
        if (isRetryableRefreshFailure(response) && attempt < REFRESH_MAX_RETRIES) {
            lastError = new Error(`Kimi Code token refresh failed with status ${response.status}`);
            continue;
        }
        const text = JSON.stringify(json);
        throw new Error(`Kimi Code token refresh failed with status ${response.status}${text ? `: ${text}` : ""}`);
    }
    throw lastError ?? new Error("Kimi Code token refresh failed");
}

async function loginKimiCoding(interaction) {
    const oauthHost = getOauthHost();
    const device = await startDeviceAuthorization(oauthHost, interaction.signal);
    interaction.notify({
        type: "device_code",
        userCode: device.userCode,
        verificationUri: device.verificationUriComplete,
        intervalSeconds: device.intervalSeconds,
        expiresInSeconds: device.expiresInSeconds,
    });
    const token = await pollForToken(oauthHost, device, interaction.signal);
    return { type: "oauth", access: token.access, refresh: token.refresh, expires: token.expires };
}

async toAuth(credential) {
        return { headers: { Authorization: `Bearer ${credential.access}` } };
    }

function requestSignal(signal) {
    return AbortSignal.any([AbortSignal.timeout(REQUEST_TIMEOUT_MS), signal]);
}

async function readJson(response) {
    try {
        const json = await response.json();
        return json && typeof json === "object" ? json : null;
    }
    catch {
        return null;
    }
}

function errorDetail(json) {
    for (const key of ["error_description", "detail", "message", "error"]) {
        const value = json?.[key];
        if (typeof value === "string" && value.trim())
            return `: ${value.trim()}`;
    }
    return "";
}

function trustedHttpUrl(value) {
    if (typeof value !== "string" || !value)
        return null;
    try {
        const url = new URL(value);
        if (url.protocol !== "https:" && url.protocol !== "http:")
            return null;
        return url.href;
    }
    catch {
        return null;
    }
}

function positiveNumber(value) {
    return typeof value === "number" && Number.isFinite(value) && value > 0 ? value : undefined;
}

async function startDeviceAuthorization(signal) {
    const response = await fetch(DEVICE_AUTHORIZATION_URL, {
        method: "POST",
        headers: {
            "Content-Type": "application/x-www-form-urlencoded",
            Accept: "application/json",
        },
        body: new URLSearchParams({ client_id: CLIENT_ID }).toString(),
        signal: requestSignal(signal),
    });
    const json = await readJson(response);
    if (!response.ok) {
        throw new Error(`Meta device authorization failed with status ${response.status}${errorDetail(json)}`);
    }
    const deviceCode = json?.device_code;
    const userCode = json?.user_code;
    const verificationUri = trustedHttpUrl(json?.verification_uri_complete) ?? trustedHttpUrl(json?.verification_uri);
    if (typeof deviceCode !== "string" || !deviceCode || typeof userCode !== "string" || !userCode || !verificationUri) {
        throw new Error(`Invalid Meta device authorization response: ${JSON.stringify(json)}`);
    }
    return {
        deviceCode,
        userCode,
        verificationUri,
        intervalSeconds: positiveNumber(json?.interval),
        expiresInSeconds: positiveNumber(json?.expires_in),
    };
}

async function pollForIdentityToken(device, signal) {
    return pollOAuthDeviceCodeFlow({
        intervalSeconds: device.intervalSeconds,
        expiresInSeconds: device.expiresInSeconds,
        waitBeforeFirstPoll: true,
        signal,
        poll: async () => {
            const response = await fetch(DEVICE_TOKEN_URL, {
                method: "POST",
                headers: {
                    "Content-Type": "application/x-www-form-urlencoded",
                    Accept: "application/json",
                },
                body: new URLSearchParams({
                    grant_type: "urn:ietf:params:oauth:grant-type:device_code",
                    device_code: device.deviceCode,
                    client_id: CLIENT_ID,
                }).toString(),
                signal: requestSignal(signal),
            });
            const json = await readJson(response);
            if (response.ok && typeof json?.access_token === "string" && json.access_token) {
                return { status: "complete", value: json.access_token };
            }
            switch (json?.error) {
                case "authorization_pending":
                    return { status: "pending" };
                case "slow_down":
